function verifySqlPassword(supplied, storedDigest) {
  if (typeof supplied !== 'string' || supplied.length === 0) return false;
  const parts = (storedDigest || '').split(':');
  if (parts.length !== 3) return false;
  const [, saltHex, keyHex] = parts;
